            long utc = parseReadingUtc(i, item.readingUtc());
            BigDecimal cumulative = parseCumulative(i, item.cumulativeVolume());
            points.add(new Point(utc, cumulative));
        }
        // 完整序列校验：批次内时刻必须严格递增，任一错误整批拒绝
