     * 评估一对相邻读数（prev 时刻严格早于 curr），按 REGRESSION、FLOW_RATE、INTERVAL_GAP
     * 固定顺序返回命中的异常（一对读数可能命中多个，如倒退且间隔超上限）。
     */
    static List<Finding> evaluate(Point prev, Point curr, Rule rule) {
        if (curr.utcNanos() <= prev.utcNanos()) {
            throw new IllegalArgumentException("evaluate 要求相邻读数时刻严格递增");
        }
        BigDecimal volumeDelta = curr.cumulative().subtract(prev.cumulative())
                .setScale(VOLUME_SCALE, RoundingMode.HALF_UP);
        BigDecimal durationMinutes = BigDecimal.valueOf(curr.utcNanos() - prev.utcNanos())
                .divide(NANOS_PER_MINUTE, DURATION_SCALE, RoundingMode.HALF_UP);
        BigDecimal actualFlowRate = volumeDelta.divide(durationMinutes, FLOW_SCALE, RoundingMode.HALF_UP);

        List<Finding> findings = new ArrayList<>(3);
        if (volumeDelta.signum() < 0) {
            findings.add(new Finding(ANOMALY_REGRESSION_CONST, volumeDelta, durationMinutes, actualFlowRate,
                    volumeDelta.negate(), null, null));
        } else if (actualFlowRate.compareTo(rule.maxFlowRate()) > 0) {
            findings.add(new Finding(ANOMALY_FLOW_RATE_CONST, volumeDelta, durationMinutes, actualFlowRate,
                    null, actualFlowRate.subtract(rule.maxFlowRate()).setScale(FLOW_SCALE, RoundingMode.HALF_UP),
                    null));
        }
        if (durationMinutes.compareTo(BigDecimal.valueOf(rule.maxIntervalMinutes())) > 0) {
            findings.add(new Finding(ANOMALY_INTERVAL_GAP_CONST, volumeDelta, durationMinutes, actualFlowRate,
                    null, null,
                    durationMinutes.subtract(BigDecimal.valueOf(rule.maxIntervalMinutes()))
                            .setScale(DURATION_SCALE, RoundingMode.HALF_UP)));
        }
        return findings;
    }

