        } catch (DateTimeParseException | ArithmeticException e) {
            throw ApiException.unprocessable("INVALID_READING",
                    where + "readingUtc 不是合法的 UTC 时刻: " + value);
        }
    }

    private static BigDecimal parseCumulative(int index, String value) {
        String where = index >= 0 ? "第 " + (index + 1) + " 条读数的 " : "替代读数的 ";
        if (value == null || value.isBlank()) {
            throw ApiException.unprocessable("INVALID_READING", where + "cumulativeVolume 不能为空");
