    private static final String ANOMALY_REGRESSION_CONST = "REGRESSION";
    private static final String ANOMALY_FLOW_RATE_CONST = "FLOW_RATE";
    private static final String ANOMALY_INTERVAL_GAP_CONST = "INTERVAL_GAP";
}

