    List<Finding> findings = new ArrayList<>(3);
    if (volumeDelta.signum() < 0) {
        findings.add(new Finding(ANOMALY_REGRESSION_CONST, volumeDelta, durationMinutes, actualFlowRate,
                volumeDelta.negate(), null, null));
